def solve(g,marker):
    g=np.array(g); H,W=g.shape
    seen=np.zeros_like(g,dtype=bool); q=deque()
    # bfs from border over cells != marker
    for y in range(H):
        for x in (0,W-1):
            if g[y,x]!=marker and not seen[y,x]: seen[y,x]=True;q.append((y,x))
    for x in range(W):
        for y in (0,H-1):
            if g[y,x]!=marker and not seen[y,x]: seen[y,x]=True;q.append((y,x))
    while q:
        y,x=q.popleft()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<H and 0<=nx<W and not seen[ny,nx] and g[ny,nx]!=marker:
                seen[ny,nx]=True;q.append((ny,nx))
    o=g.copy()
    for y in range(H):
        for x in range(W):
            if o[y,x]==g.flat[0] or True: pass
    bg=g[0,0]
    o=o.copy(); 
    for y in range(H):
        for x in range(W):
            if o[y,x]==bg and not seen[y,x]: o[y,x]=3
    return o.tolist()
