G=load()
def f(I):
    I=np.array(I); H,W=I.shape; out=I.copy()
    cnt=Counter(I.ravel()); bg=cnt.most_common(1)[0][0]
    pset={(i,j) for i in range(H) for j in range(W) if I[i,j]!=bg}
    R=defaultdict(list); C_=defaultdict(list); D1=defaultdict(list); A=defaultdict(list)
    for i,j in pset: R[i].append(j); C_[j].append(i); D1[i-j].append((i,j)); A[i+j].append((i,j))
    segs=set()
    for kk,vv in list(R.items())+list(C_.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]):
            for rr in range(a+1,b):
                if (kk,rr) not in pset: segs.add((kk,rr))
    for kk,vv in list(D1.items())+list(A.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]):
            dr,dc=b[0]-a[0],b[1]-a[1]
            if dr==0 or dc==0 or abs(dr)!=abs(dc): continue
            L=max(abs(dr),abs(dc))
            sgn_d=(1 if dr>0 else -1); sgn_c=(1 if dc>0 else -1)
            for tt in range(1,L):
                c=(a[0]+sgn_d*tt,a[1]+sgn_c*tt)
                if c not in pset: segs.add(c)
    for (i,j) in segs:
        if 0<=i<H and 0<=j<W and out[i,j]==0: out[i,j]=3
    return out
