from collections import Counter, defaultdict
def segs_of(name):
    II=np.array(G[name+' input']); OO=np.array(G[name+' output'])
    H,W=II.shape
    bgc=Counter(II.ravel()).most_common(1)[0][0]
    P={(i,j) for i in range(H) for j in range(W) if II[i,j]!=bgc}
    D={(i,j) for i in range(H) for j in range(W) if OO[i,j]!=II[i,j]}
    Rr=defaultdict(list); Cc=defaultdict(list); D1d=defaultdict(list); Ad=defaultdict(list)
    for i,j in P: Rr[i].append(j); Cc[j].append(i); D1d[i-j].append((i,j)); Ad[i+j].append((i,j))
    segs=[]
    for kk,vv in list(Rr.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]): segs.append(('r',kk,a,b))
    for kk,vv in list(Cc.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]): segs.append(('c',kk,a,b))
    for kk,vv in list(D1d.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]):
            dr,dc=b[0]-a[0],b[1]-a[1]
            if abs(dr)!=abs(dc) or dr==0: continue
            segs.append(('d',kk,a,b))
    for kk,vv in list(Ad.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]):
            dr,dc=b[0]-a[0],b[1]-a[1]
            if abs(dr)!=abs(dc) or dr==0: continue
            segs.append(('a',kk,a,b))
    fills=set()
    for typ,kk,a,b in segs:
        if typ=='r':
            lo,hi=min(a,b),max(a,b)
            for t in range(lo,hi+1): fills.add((kk,t))
        elif typ=='c':
            lo,hi=min(a,b),max(a,b)
            for t in range(lo,hi+1): fills.add((t,kk))
        else:
            dr,dc=b[0]-a[0],b[1]-a[1]; sgn=(dr>0)-(dr<0); sc=(dc>0)-(dc<0); L=max(abs(dr),abs(dc))
            if typ=='d': cells=[(a[0]+sgn*t,a[1]+sc*t) for t in range(L)]
            else: cells=[(a[0]+sgn*t,a[1]-sc*t) for t in range(L)]
            fills.update(cells)
    extra=fills-D-P; miss=D-fills
    return II,O,D,P,fills,extra,miss,len(segs),segs
