from collections import Counter, defaultdict

def seglist(I):
    H,W=I.shape
    bgc=Counter(I.ravel()).most_common(1)[0][0]
    P={(i,j) for i in range(H) for j in range(W) if I[i,j]!=bgc}
    Rr=defaultdict(list); Cc=defaultdict(list); Dd=defaultdict(list); Ad_=defaultdict(list)
    for i,j in P: Rr[i].append(j); Cc[j].append(i); Dd[i-j].append((i,j)); Ad_[i+j].append((i,j))
    s=[]
    for kk,vv in list(Rr.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]): s.append(('r',kk,a,b))
    for kk,vv in list(Cc.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]): s.append(('c',kk,a,b))
    for kk,vv in list(Dd.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]):
            dr,dc=b[0]-a[0],b[1]-a[1]
            if abs(dr)!=abs(dc): continue
            s.append(('d',kk,a,b))
    for kk,vv in list(Ad_.items()):
        vv=sorted(vv)
        for a,b in zip(vv[:-1],vv[1:]):
            dr,dc=b[0]-a[0],b[1]-a[1]
            if abs(dr)!=abs(dc): continue
            s.append(('a',kk,a,b))
